SELECT JSON_OBJECT('row',JSON_OBJECT(CONVERT(X'636f756e7473' USING utf8mb4),JSON_OBJECT(CONVERT(X'513039' USING utf8mb4),COALESCE(SUM(CASE WHEN 1=1 THEN 1 ELSE 0 END),0),CONVERT(X'513130' USING utf8mb4),COALESCE(SUM(CASE WHEN a.province IN (CONVERT(X'e5b9bfe4b89ce79c81' USING utf8mb4),CONVERT(X'e5b9bfe4b89c' USING utf8mb4)) THEN 1 ELSE 0 END),0),CONVERT(X'513131' USING utf8mb4),COALESCE(SUM(CASE WHEN a.province IN (CONVERT(X'e5b9bfe4b89ce79c81' USING utf8mb4),CONVERT(X'e5b9bfe4b89c' USING utf8mb4)) AND a.city IN (CONVERT(X'e5b9bfe5b79ee5b882' USING utf8mb4),CONVERT(X'e5b9bfe5b79e' USING utf8mb4)) AND p.education IN (CONVERT(X'44415a4855414e' USING utf8mb4),CONVERT(X'47414f5a4849' USING utf8mb4)) THEN 1 ELSE 0 END),0),CONVERT(X'513132' USING utf8mb4),COALESCE(SUM(CASE WHEN a.province IN (CONVERT(X'e5b9bfe4b89ce79c81' USING utf8mb4),CONVERT(X'e5b9bfe4b89c' USING utf8mb4)) AND a.city IN (CONVERT(X'e6b7b1e59cb3e5b882' USING utf8mb4),CONVERT(X'e6b7b1e59cb3' USING utf8mb4)) AND p.experience IN (CONVERT(X'47524144554154494e47' USING utf8mb4),CONVERT(X'4f4e5f43414d505553' USING utf8mb4)) THEN 1 ELSE 0 END),0)))) FROM (SELECT DISTINCT pc.position_id FROM c_position_chain pc WHERE pc.deleted=0 AND pc.industry_chain_id IN (19,1063,1130,1169,15926,15927,15928,15929,15930,15931,15932,15933,15934,15935,15936,15937,15938,15939,15940,15941,15942,15943,15944,15945,15946,15947,15948,15949,15950,15951,15952,15953,15954,15955,15956,15957,15958,15959,15960,15961,15962,15963,15964,15965,15966,15967,15968,15969,15970,15971,15972,15973,15974,15975,15976,15977,15978,15979,15980,15981,15982,15983,15984,15985,15986,15987,15988,15989,15990,15991,15992,15993,15994,15995,15996,15997,15998)) industry_candidates JOIN c_company_position p ON p.id=industry_candidates.position_id LEFT JOIN c_company_address a ON a.id=p.company_address_id WHERE p.publish_state='PUBLISHING' AND p.deleted=0;
